W.append(dict(
    key='pfalz_zweibruecken_1557_long', doc=967, year=1557,
    order='Pfalz-Zweibrücken, Kirchenordnung (Pfalzgraf Wolfgang)',
    territory='Palatinate-Zweibrücken (and Neuburg)',
    citation='Sehling 18, I/5, pp. 193–195',
    family='B1. Württemberg long form', form='bidding + collect',
    tradition='Lutheran',
    position='Immediately after the sermon, chiefly on the high feasts (Christmas, Easter, Pentecost) and whenever the sermon has not been long; otherwise the shorter form is to be read.',
    heading='[Das Allgemeine Kirchengebet — Ausführliche Form] Die vorrede des gemeinen Gebets',
    heading_en='[The general prayer of the Church — full form] The preface of the common prayer',
    notes='From Pfalz-Neuburg 1554 / Württemberg 1553. The collect for the magistrates is replaced by a Melanchthonian prayer (“der du … Obrigkeyt und ordenliche Regiment selb in menschliche Natur geordent”). Rubric after the Our Father: “Dises gebet, dieweil es zimlich lang ist, mögen die Kirchendiener etwan an den grossen Festen gebrauchen … sonst sollen sie die kürtzere form … gemeinigklich dem Volck fürlesen.”',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_long', 1),
          r='Die vorrede des gemeinen Gebets.',
          b='Nach dem wir bey einander in gottes namen versamlet sind und uns bevolhen ist, Das wir Got in aller unser not sollen anrüffen, auch für menigklich unser fürbit thun, Zu welchen wir die zusagung unsers lieben Herrn Jesu Christi haben: Wo zwen unter euch eins werden auff erden, warumb es ist, das sie bitten wöllen, das soll inen von meinem Vatter im Hymel widerfaren, Und: bittet, so wird euch gegeben, suchet, so werdet ir finden, Klopffet an, so wirdt euch auffgethan.',
          tr_sub=[('our dear Lord Christ:', 'our dear Lord Jesus Christ:')]),
        P('church', sub='ministers',
          b='So bittet also.', b_en='So pray ye thus.',
          p='O Almechtiger, ewiger, gütiger Got und vater unsers Herrn Jesu Christi, der uns erstlich bevolhen hat, Das wir dich umb arbeiter in dein ernde bitten sollen, Wir bitten dein grundtlose barmhertzigkeit, du wöllest uns rechtschaffene lehrer und diener deines götlichen worts zuschicken, und denselben dein heilsames wort in ir hertz und mund geben, das sie deine bevelch treulich außrichten und nichts predigen, das deinem wort entgegen sey, auff das wir durch dein Hymlisch ewig wort ermanet, gelert, gespeyset, getröst und gesterckt werden und thun, was dir gefellig und uns fruchtbarlich ist, Gibe, Herr, deiner heyligen Christenheyt deinen Geyst und Göttliche weyßheyt, das dein wort unter uns lauffe und wachse und mit aller freydigkeit, wie sichs gebürt, geprediget und dein heylige Christliche gemein dardurch gebessert werde, Auff das wir in bestendigem glauben dir dienen und in erkandtnuß deines Namens biß an das ende verharren, Amen.',
          tr_from=('wuerttemberg_1553_long', 2),
          tr_sub=[('O almighty, gracious God', 'O almighty, everlasting, gracious God'),
                  ('who hath earnestly commanded', 'who hath first commanded'),
                  ('preach nothing that is contrary to thy holy word', 'preach nothing that is contrary to thy word'),
                  ('that we may serve thee with steadfast faith', 'that we may serve thee in steadfast faith')],
          note='The church bidding of Württemberg 1553 (“Hierauff … bitten für die gemein Christlich Kirche und derselben Diener”) survives only in the draft (apparatus); the print has just “So bittet also”. “erstlich” (sic) for “ernstlich”.'),
        P('civil-authority',
          r='Für die weltlich Obrigkeit.',
          b='Lasset uns trewlich bitten, auß bevelch unsers Herrn Jesu Christi und seiner Aposteln, für unsere Obrigkeyt, das wir ein ruewigs stilles leben in aller Gottseligkeyt fürn mögen.',
          p='Almechtiger Gott, Ewiger Vater unsers Herrn und heilands Jesu Christi, der du sambt deinem son und heiligen geist alle Creaturen erschaffen hast, Und hast Obrigkeyt und ordenliche Regiment selb in menschliche Natur geordent und bist gewißlich selbst der erhalter, sovil darinn guter ordnung bleiben, Und wilt, das dein gesetz und straff zeugnuß sind von deiner gegenwertigkeyt im menschlichen geschlecht und von deiner Weißheit und gerechtigkeyt, Wir bitten dich mit hertzen, du wöllest gnedigklich alle Christliche Obrigkeit und unser Herrschafft, Rethe und Regenten mit deinem wort und heyligen Geyst regieren und inen weyßheyt, rechten und glückseligen rath geben und sie bewaren wider alle teuffels tück und mord, und in disen Landen Christliche lehr, einigkeyt der Prediger, Selige und fridliche Regierung allezeyt erhalten zu deinem lob und viler Menschen seligkeit, umb deß Herrn Christi willen, Amen.',
          tr_from=('wuerttemberg_1553_long', 3),
          tr_sub=[('for all temporal magistrates, that we may lead a quiet and still life in all godliness. Pray ye thus:',
                   'for our magistrates, that we may lead a quiet and still life in all godliness.')],
          p_en='Almighty God, everlasting Father of our Lord and Saviour Jesus Christ, who together with thy Son and Holy Ghost hast created all creatures, and hast thyself ordained magistracy and orderly government in the nature of man, and art surely thyself the preserver thereof, so far as good order abideth therein; and willest that thy law and punishment be a witness of thy presence among mankind and of thy wisdom and righteousness: we beseech thee with our hearts that thou wouldest graciously govern all Christian magistrates and our lordship, counsellors and rulers with thy word and Holy Spirit, and give them wisdom and right and prosperous counsel, and preserve them against all the devil’s wiles and murder, and in these lands evermore maintain Christian doctrine, unity of the preachers, and blessed and peaceable government, to thy praise and the salvation of many men; for the Lord Christ’s sake. Amen.',
          note='Pfalz-Neuburg 1554 has here the Württemberg collect.'),
        P('afflicted', sub='calamities; persecuted',
          r='Für allerley ubertrettung und anfechtung.', r_en='For all manner of transgression and temptation.',
          b='Lasset uns beten für alle die, so in bekümmernuß und anfechtung von wegen Kranckheyten, thewrung, Krieg, gefengnuß, Pestilentz und mit allerley widerwertigkeyt beschwerdt und beladen sind, Das inen Gott hilff und beystand in irer noth gnedigklich beweisen wölle, Amen. Bittend also:',
          p='O Allmechtiger Herr Gott, der du der elenden Seufftzen nicht verschmehest und der betrübten Hertzen verlangen nit verachtest und gesprochen hast: Rüff mich an in der zeyt der not, so will ich dich erretten, nimme an unser Gebett, welchs wir dir in unser noth fürbringen, und erhöre uns gnedigklich, das alles, so baide, von Teufeln und menschen wider uns strebt, zu nichte und von der gnad deiner güte zertrennet werde, auff das wir, von aller anfechtung unversert, dir in deiner gemein dancken und dich alle zeyt loben, Durch Jesum Christum unsern Herrn, Amen.',
          tr_from=('wuerttemberg_1553_long', 4),
          tr_sub=[('by reason of sickness,', 'by reason of sicknesses,'),
                  ('succour in their need. Pray ye thus:', 'succour in their need. Amen. Pray ye thus:'),
                  ('the desire of the sorrowful hearts: look thou upon our prayer,',
                   'the desire of the sorrowful hearts, and hast said: Call upon me in the day of trouble, and I will deliver thee: accept our prayer,'),
                  ('both from the devil and from men', 'both from devils and from men')],
          note='Rubric “ubertrettung” (Pfalz-Neuburg 1554: “bekümmernuß”). Adds Ps 50:15.'),
        P('peace', tr_from=('wuerttemberg_1553_long', 5),
          r='Für einen gemeinen frid.',
          b='Lasset uns auch gar ernstlich umb einen gemeinen Landtfriden bitten, das rechte Gottesdienst under uns auffwachse und Christliche zucht zuneme. Bittend also:',
          p='O Almechtiger, ewiger Gott, ein König der ehren und ein Herr hymels und der erden, durch welches Geyst alle ding regiert, durch welchs fürsehung alle ding geordnet werden, der du bist ein Gott deß fridens, von dem allein alle einigkeyt zu uns kompt, Wir bitten durch unsern Herrn Jesum Christum, du wöllest uns unsere sünd vergeben und mit deinem Götlichen frid und einigkeyt begnaden, damit wir in forcht und zittern dir dienen, zu lob und preiß deines namens, Amen.',
          tr_sub=[('Almighty, everlasting God, a King of glory', 'O almighty, everlasting God, a King of glory'),
                  ('we beseech thee through our Lord', 'we beseech through our Lord')]),
        P('enemies', tr_from=('wuerttemberg_1553_long', 6),
          r='Für die feynd.',
          b='Last uns auch bitten für unsere Feindt, das Gott sie mit gnaden bedencke und inen, was zu irem heil nützlich und nottürfftig ist, gnedigklich verleihen wölle. Bittet also:',
          p='Almechtiger ewiger Gott, der du uns befolhen hast, das wir unsere feindt lieb haben sollen, denen, die uns beleydigen, guts thun, und für unsere verfolger bitten. Wir schreyen ernstlich zu dir, das du all unsere feinde wöllest gnedigklich heimsuchen, inen ware rewe irer sünden verleyhen, auch mit uns und der gantzen Christenheyt ein freundlichs gottförchtiges, einhelliges gemüt und hertz geben, durch unsern Herrn Jesum Christum, Amen.'),
        P('childbirth', tr_from=('wuerttemberg_1553_long', 7),
          r='Für alle schwangere frawen.',
          b='Lasset uns auch bitten für alle schwangere Weiber, Das sie Gott gnedigklich von Kindßbanden erlösen wölle. Bittend also:',
          p='Almechtiger ewiger Gott und Vater, ein schöpffer aller ding, der du Mann und Weyb gnedigklich gesegnet hast Und dem weib iren schmertzen, zugeberen, zu einem heyligen Creutze gesegnet hast, wir bitten dich, gütiger Vatter, du wöllest die früchte ihres leybs erhalten und bewaren und unter dem Creutz in der bekümmerlichen gepurt nicht verderben, sonder gnedigklich und mit freuden deiner hilff empfinden lassen, Durch Jesum Christum, deinen lieben Son, Amen.'),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_long', 8),
          r='Für die frücht der erden.',
          b='Last uns auch bitten für die früchte der erden, das sie Gott wölle segnen und uns, dieselben in seinem gehorsam zuniessen, gnedigklich verleyhen. Bittend also:',
          p='Almechtiger ewiger Got, der du durch dein wort alle ding erschaffest und segnest, Wir bitten dich, das du dein wort, unsern Herrn Jesum Christum, in unsere hertzen pflantzest, dardurch an uns gesegnet werde mit fruchtbarer wachsung und Götlichem gebrauch alles, was uns zur leyblichen notturfft dienet.',
          tr_sub=[('in our heart,', 'in our hearts,')]),
        P('lords-prayer', sub='conclusion', tr_from=('wuerttemberg_1553_long', 9),
          b='Lasset uns auch bitten für alles das, dafür unser Herr Got will gebeten sein, sprecht Vatter unser etc.'),
    ]))

W.append(dict(
    key='pfalz_zweibruecken_1557_short', doc=967, year=1557,
    order='Pfalz-Zweibrücken, Kirchenordnung (Pfalzgraf Wolfgang)',
    territory='Palatinate-Zweibrücken (and Neuburg)',
    citation='Sehling 18, I/5, pp. 195–196',
    family='B2. Württemberg short form', form='exhortation + continuous prayer',
    tradition='Lutheran',
    position='After the sermon; the ordinary form (“gemeinigklich dem Volck fürlesen”), the long form being kept for high feasts.',
    heading='Ein kürtzere form des gemeinen Gebets',
    heading_en='A shorter form of the common prayer',
    notes='Petition 2 names the ruling duke (“N.”; KO 1560/1570/1600 insert Emperor and “Hertzog Wolffgang Pfaltzgraven”).',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_short', 1),
          r='Ein kürtzere form des gemeinen Gebets.', r_en='A shorter form of the common prayer.',
          b='Ir geliebten in Christo, Dieweil wir alle glieder eines leybs sind, welchs haupt Christus ist, So soll sich ye ein glid des andern annemen und für einander bitten, das sollen wir auß befelh unsers Herrn Christi und seiner heiligen Apostel von hertzen gern thun. Bittend also:',
          tr_sub=[('and of his holy Apostle.', 'and of his holy Apostles.')]),
        P('church', sub='ministers', tr_from=('wuerttemberg_1553_short', 2),
          p='Almechtiger, Barmhertziger Gott, ewiger Vatter unsers heylands Jesu Christi, erschaffer, sampt deinem son und Heiligen geist, Wir bitten dich hertzlich, du wöllest dein heylige Kirch mit iren dienern durch den heiligen Geist regiren, Auff das sie bei der rechtschaffenen weid deines Almechtigen und ewigen worts erhalten werden, dardurch der glaub gegen dir gesterckt und die lieb gegen allen menschen in uns erwachse und zuneme.',
          tr_sub=[('Almighty, merciful, everlasting God and Father, a Lord of heaven and of earth:',
                   'Almighty, merciful God, everlasting Father of our Saviour Jesus Christ, Creator together with thy Son and Holy Ghost:')]),
        P('civil-authority', tr_from=('wuerttemberg_1553_short', 3),
          p='Wöllest auch unser Oberkeyt, insonderheitt unsern Gnedigen Herren und Landsfürsten N. sampt allen Reten und Amptleuten gnad und eynigkeyt verleihen, die unterthanen nach deinem Göttlichen willen und wolgefallen zu regiern, auff das die gerechtigkeyt gefürdert, die bößheyt verhindert und gestrafft werde, damit wir in stiller rhue und gutem friden, als Christen gebürt, unser leben volstrecken mögen.',
          tr_sub=[('Vouchsafe also unto the temporal magistrates, the Roman Emperor, all kings, princes and lords, but especially unto our gracious lord and prince of this land, and also the whole house of Württemberg, together with all their counsellors and officers,',
                   'Vouchsafe also unto our magistrates, especially unto our gracious lord and prince of this land N., together with all counsellors and officers,')]),
        P('enemies', tr_from=('wuerttemberg_1553_short', 4),
          p='Das auch unsere feind und widersacher ablassen und sich mit uns fridlich und senfftigklich zu leben begeben wöllen.'),
        P('afflicted', sub='childbirth; persecuted', tr_from=('wuerttemberg_1553_short', 5),
          p='Alle die, so in trübsal, armut, kranckheit, kindsbanden und anderer anfechtung sindt, auch die, so umb deines heiligen Namens und der warheyt willen angefochten, gefangen oder sonst verfolgung leiden, tröste sie, O Got, mit deinem heyligen Geist, das sie solches alles für deinen vetterlichen willen auffnemen und erkennen.'),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_short', 6),
          p='Wöllest uns auch alle frücht der erden, zur leyblichen notturfft gehörig, mit fruchtbarer wachsung geraten und gedeyen lassen.'),
        P('conclusion', tr_from=('wuerttemberg_1553_short', 7),
          p='Auch bitten wir für alles das, dafür du, O ewiger Gott, gebeten sein wilt, das du uns solchs gnedigklich verleyhest, Durch das bitter leyden und sterben Christi Jesu, deines einigen Sons, unsers geliebten Herrn und heylands, Welcher mit dir und dem heyligen Geyst lebt und regiert, warer und gleycher Gott, hochgelobt in ewigkeyt, Amen.',
          tr_sub=[('for which thou, everlasting God,', 'for which thou, O everlasting God,'),
                  ('liveth and reigneth, equal God', 'liveth and reigneth, true and equal God')]),
    ]))

