W.append(dict(
    key='leiningen_westerburg_1566', doc=1074, year=1566,
    order='Leiningen-Westerburg, Kirchenordnung (Graf Philipp)',
    territory='County of Leiningen-Westerburg',
    citation='Sehling 19, IV/3, pp. 254–255',
    family='B1. Württemberg long form', form='preface + bidding + headed collects',
    tradition='Lutheran',
    position='After the sermon (Ordnung des gemeinen Gebets unnd Letaney).',
    heading='Die Vorred des gemeinen Gebets',
    heading_en='The preface of the common prayer',
    notes='Preface and church petition from Pfalz-Zweibrücken 1557; the rest from Pfalz-Neuburg 1554, but the biddings before each collect are dropped, leaving headed collects. No Our Father is printed; the collect bank for feasts follows directly.',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_long', 1),
          r='Die Vorred des gemeinen Gebets.',
          b='Nach dem wir bey einander in Gottes namen versamlet unnd uns befolhen ist, daß wir Gott in all unser not sollen anrüffen, auch für meniglich unser fürbitt thun, zu wölchen wir die zusagung unsers lieben Herrn Jesu Christi haben: Wo zween oder drey unter euch eins werden, warumb es ist, daß sie bitten wöllen, das sol inen von meinem Vatter im Himmel widerfahren. Und: Bittet, so würt euch gegeben, suchet, so werdet ir finden, klopfft an, so würt euch auff than.',
          tr_sub=[('our dear Lord Christ: Where two of you', 'our dear Lord Jesus Christ: Where two or three of you')]),
        P('church', sub='ministers', tr_from=('wuerttemberg_1553_long', 2),
          b='Hierauff lasset uns auß warem vertrawen zu Göttlicher barmhertzigkeit durch unsern Herrn Jesum Christum bitten für die gemeine Christliche Kirche und derselbigen Diener. Bittet also:',
          p='O Allmechtiger, Ewiger, gütiger Gott und Vatter unsers Herrn Jesu Christi, der uns ernstlich befolhen hat, daß wir dich umb treuwe arbeiter inn deine Erndte bitten sollen. Wir bitten deine grundtlose barmhertzigkeit, du wöllest uns rechtschaffene lehrer und diener deines Göttlichen worts zuschikken, Matthei 9. unnd Lucae 10. Cap., und denselbigen dein heilsames wort inn ir hertz unnd mund geben, daß sie deinen befelch trewlich außrichten und nichts predigen, das deinem heiligen wort entgegen sey, auff das wir durch dein Himlisch, ewiges wort ermahnet, gelehrt, gespeiset, getröst und gesterckt werden und thun, was dir gefellig und uns fruchtbarlich ist. Gib, Herr, deiner heiligen Christenheit deinen Geist und Göttliche weißheit, daß dein wort unter uns lauffe unnd wachse und mit aller freydigkeit, wie sichs gebürt, geprediget unnd deine heilige Christliche gemein dardurch gebessert werde, auff das wir mit bestendigem Glauben dir dienen unnd inn erkentnuß deines namens biß an das ende verharren, Amen.',
          tr_sub=[('O almighty, gracious God', 'O almighty, everlasting, gracious God'),
                  ('pray thee for labourers into thine harvest', 'pray thee for faithful labourers into thine harvest'),
                  ('ministers of thy divine word, and give', 'ministers of thy divine word (Matthew 9 and Luke 10), and give')]),
        P('civil-authority', tr_from=('wuerttemberg_1553_long', 3),
          r='Für die Weltliche Obrigkeit.',
          p='Allmechtiger, Ewiger Gott, inn wölches hand bestehet aller menschen gewalt und Obrigkeit, von dir zur straff der bösen unnd wolfart der frommen eingesetzet, inn wölches hand auch stehen alle Recht und Gesetz auff Erden. Wir bitten dich, sihe gnediglich auff deine Diener, den Römischen Kayser, alle Könige, Fürsten und ordenliche Obrigkeit unnd sonderlich auff unsern gnedigen und wolgebornen Herrn, Graffen Philippum, auch alle irer gnaden verwanten, Rhät und Amptleut, damit sie das Weltliche Schwerdt, ihnen von dir befolhen, nach deinem befelch inn deiner forcht führen mögen. Erleuchte unnd erhalte sie bey deinem Göttlichen namen, Gib ihnen, lieber Herr, Weißheit und verstand und ein fridlich Regiment, auff das sie alle ihre unterthanen in fried, ruhe und einigkeit beschirmen und regiren, erlenger inen, O Gott unsers Heils, ire tag, auff das wir unter irer Herrschafft deinen Göttlichen namen sampt inen heiligen unnd preisen mögen, durch unsern Herren Jesum Christum, Amen.',
          tr_sub=[('all the rights and laws of all realms upon earth', 'all rights and laws upon earth'),
                  ('our gracious prince and lord of this land, and also all his counsellors and officers',
                   'our gracious and well-born lord, Count Philip, and also all his Grace’s kinsmen, counsellors and officers'),
                  ('we may hallow and praise thy divine name', 'we together with them may hallow and praise thy divine name')]),
        P('afflicted', tr_from=('wuerttemberg_1553_long', 4),
          r='Für alle bekümmernuß und anfechtung.', r_en='For all trouble and temptation.',
          p='O Allmechtiger Herre Gott, der du der elenden seufftzen nicht verschmehest und der betrübten hertzen verlangen nicht verachtest, sihe doch an unser Gebet, wölches wir dir inn unser nott fürbringen, unnd erhöre uns gnediglich, daß alles, so beyde, vom Teuffel unnd Menschen, wider uns strebt, zunicht unnd nach dem raht deiner güte zertrennet werde, auff daß wir, von aller anfechtung unverseret, dir in deiner Gemeine dancken und dich allezeit loben, durch Jesum Christum, unseren Herren, Amen.',
          tr_sub=[('by the grace of thy goodness', 'according to the counsel of thy goodness')]),
        P('peace', tr_from=('wuerttemberg_1553_long', 5),
          r='Umb ein gemeinen frieden.', r_en='For a common peace.',
          p='Allmechtiger, Ewiger Gott, ein König der Ehren unnd ein Herr Himmels unnd der Erden, durch wölches Geist alle ding regiret, durch wölches versehung alle ding geordnet werden, Der du bist ein Gott des fridens, von dem allein alle einigkeit zu uns kompt, Wir bitten dich durch unsern Herrn Jesum Christum, du wöllest uns unsere sünde vergeben unnd mit deinem Göttlichen frieden und einigkeit begnaden, damit wir in forcht unnd zittern dir dienen, zu lob und preiß deines namens, Amen.'),
        P('enemies', tr_from=('wuerttemberg_1553_long', 6),
          r='Für die Feinde.',
          p='Allmechtiger, Ewiger Gott, der du uns befolhen hast, daß wir unsere feinde lieb haben sollen, denen, die uns beleidigen, guts thun unnd für unsere verfolger bitten. Wir schreyen ernstlich zu dir, daß du alle unsere feinde gnediglich wöllest heimsuchen, inen ware rew irer sünden verleihen, auch in uns und der gantzen Christenheit ein freundtliches, Gottsförchtiges, einhelliges gemüt und hertz geben, durch unsern Herrn Jesum Christum, Amen.',
          tr_sub=[('and give them, together with us and the whole of Christendom,', 'and give, in us and in the whole of Christendom,')]),
        P('childbirth', tr_from=('wuerttemberg_1553_long', 7),
          r='Für alle schwangere Weiber.',
          p='Allmechtiger, Ewiger Gott unnd Vatter, ein Schöpffer aller ding, Der du Mann und Weib gnediglich gesegnet und dem Weib iren schmertzen zu gebeeren zu einem heiligen Creutz gesegnet hast. Wir bitten dich, gütiger Vatter, du wöllest die früchte ires Leibs erhalten unnd bewaren und unter dem creutz in der kümmerlichen geburt nicht verderben, sondern gnediglich und mit frewden deiner hülff entpfinden lassen, durch Jesum Christum, deinen lieben Son, unsern Herrn, Amen.',
          tr_sub=[('through Jesus Christ thy dear Son. Amen.', 'through Jesus Christ thy dear Son, our Lord. Amen.')]),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_long', 8),
          r='Für die früchte der Erden.',
          p='Herr Gott, Himlischer Vatter, der du durch dein wort alle ding erschaffest unnd segnest. Wir bitten dich, daß du dein Wort, unsern Herren Jesum Christum, inn unsere hertzen pflantzest, dardurch an uns gesegnet werde mit fruchtbarer wachsung und Göttlichem gebrauch alles, was uns zur leiblichen notturfft dienet, Amen.',
          tr_sub=[('Almighty, everlasting God, who by thy word', 'Lord God, heavenly Father, who by thy word'),
                  ('in our heart,', 'in our hearts,'), ('bodily need may be blessed unto us with fruitful increase and godly use.', 'bodily need may be blessed unto us with fruitful increase and godly use. Amen.')]),
    ]))

W.append(dict(
    key='kurpfalz_1556_short', doc=480, year=1556,
    order='Kurpfalz, Kirchenordnung (Ottheinrich)',
    territory='Electoral Palatinate',
    citation='Sehling 14, Regierungszeit Ottheinrichs, pp. 157–159',
    family='B2. Württemberg short form', form='exhortation + continuous prayer',
    tradition='Lutheran',
    position='After the sermon, when the long form cannot be read.',
    heading='Ein kürtzere form des gemeinen gebets',
    heading_en='A shorter form of the common prayer',
    notes='From Pfalz-Neuburg 1554 / Württemberg 1553. The 1577 edition adds an alternative prayer “nach dem heiligen vaterunser gericht” (apparatus, not taken in).',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_short', 1),
          r='Ein kürtzere form des gemeinen gebets. Nachdem sich aber zu zeiten etlich zufäll begeben, das die gebet nach der leng nicht wol erzelt mögen werden, so mag alßdann das volgend gebet, darin alles anligen der kirchen kürtzlich begriffen, nach der predig fürgesprochen werden:',
          b='Ir geliebten in Christo, dieweil wir alle glider eines leibs seind, welches haupt Christus ist, so soll sich je ein glid des andern annemen und für einander bitten, das sollen wir aus bevelch unsers herrn Christi und seines heiligen apostels von hertzen gern thun. Bittet also:'),
        P('church', sub='ministers', tr_from=('wuerttemberg_1553_short', 2),
          p='Allmechtiger, barmhertziger, ewiger Gott und vater, ein herr himmels und der erden, wir bitten dich hertzigklich, du wöllest dein heilige kirche mit iren dienern durch den heilgen geist regieren, auf das sie bey der rechtgschaffnen waid deines allmechtigen und ewigen worts erhalten werden, dardurch der glaub gegen dir gesterckt und die lieb gegen allen menschen in uns erwachse und zuneme.'),
        P('civil-authority', tr_from=('wuerttemberg_1553_short', 3),
          p='Wöllest auch der weltlichen oberkeit, dem römischen keiser, allen königen, fürsten und herrn, insonderheit aber unserm gnedigsten chur- und landsfürsten, hertzog Ottheinrichen, pfaltzgraven etc., sampt allen irer churfürstlichen gnaden räthen und amptleuten gnad und einigkeit verleihen, die underthonen nach deinem göttlichen willen und wolgefallen zu regieren, auf das die gerechtigkeit gefürdert, die boßheit verhindert und gestraft werde, damit wir in stiller ruw und gutem friden, als Christen gebürt, unser leben volstrecken mögen.',
          tr_sub=[('but especially unto our gracious lord and prince of this land, and also the whole house of Württemberg, together with all their counsellors and officers,',
                   'but especially unto our most gracious Elector and prince of this land, Duke Otto Henry, Count Palatine, etc., together with all his Electoral Grace’s counsellors and officers,')]),
        P('enemies', tr_from=('wuerttemberg_1553_short', 4),
          p='Das auch unsere feind und widersächer ablassen und sich mit uns fridlich und sänftigklich zu leben begeben wöllen.'),
        P('afflicted', sub='childbirth; persecuted', tr_from=('wuerttemberg_1553_short', 5),
          p='Alle die, so in trübsal, armut, kranckheit, kindsbanden und anderer anfechtungen seind, auch die, so umb deines heiligen namens und der warheit willen angefochten, gefangen sein oder sonst verfolgung leiden, tröst sie, o Gott, mit deinem heiligen geist, das sie solches alles für deinen väterlichen willen aufnemen und erkhennen.',
          tr_sub=[('and other temptation,', 'and other temptations,'), ('assailed, taken captive,', 'assailed, are taken captive,')]),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_short', 6),
          p='Wöllest uns auch alle frucht der erden, zur leiblichen notdurft gehörig, mit fruchtbarer wachsung geraten und gedeyhen lassen.'),
        P('conclusion', tr_from=('wuerttemberg_1553_short', 7),
          p='Auch bitten wir für alles, darfür du, o ewiger Gott, gebeten sein wilt, das du uns sollichs gnedigklich verleihest durch das bitter leiden und sterben Christi Jesu, deines einigen sons, unsers geliebten herrn und heilands, welcher mit dir und dem heiligen geist lebt und regiert, warer und gleicher Gott, hochgelobt in ewigkeit, Amen.',
          tr_sub=[('for which thou, everlasting God,', 'for which thou, O everlasting God,'),
                  ('liveth and reigneth, equal God', 'liveth and reigneth, true and equal God')]),
    ]))

W.append(dict(
    key='rothenburg_1559', doc=301, year=1559,
    order='Rothenburg ob der Tauber, Kirchenordnung',
    territory='Rothenburg ob der Tauber (Imperial city)',
    citation='Sehling 11, VI.1, pp. 587–588',
    family='B2. Württemberg short form', form='exhortation + continuous prayer',
    tradition='Lutheran',
    position='Always on Sundays and feast days after the sermon; the Litany is the second form.',
    heading='Ein kurze form des gemeinen gebets, so allwegen am sontag und feiertagen nach der predig dem volk soll fürgesprochen werden',
    heading_en='A short form of the common prayer, which shall always be said to the people on Sundays and feast days after the sermon',
    notes='Württemberg 1553 introduction (Ordnung des gemeinen gebets) taken over, but only the short form is printed, as the ordinary Sunday prayer.',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_short', 1),
          r='Ein kurze form des gemeinen gebets, so allwegen am sontag und feiertagen nach der predig dem volk soll fürgesprochen werden.',
          r_en='A short form of the common prayer, which shall always be said to the people on Sundays and feast days after the sermon.',
          b='Ir geliebten in Christo, dieweil wir alle glieder eines leibs sind, welches haupt Christus ist, so soll sich je ein glied des andern annemen und für einander bitten. Das sollen wir aus befelch unsers Herrn Christi und seines heiligen apostels S. Pauli von herzen gern tun. Bittet also:',
          tr_sub=[('and of his holy Apostle.', 'and of his holy Apostle Saint Paul.')]),
        P('church', sub='ministers', tr_from=('wuerttemberg_1553_short', 2),
          p='Almechtiger, barmherziger, ewiger Gott und Vater unsers Herrn Jesu Christi, ein Herr himels und der erden, wir bitten dich herziglich, du wöllest dein heilige kirchen mit iren dienern durch den Heiligen Geist regiren, auf das sie bei der rechtgeschaffen weid deines almechtigen und ewigen worts erhalten werden, dardurch der glaub gegen dir gesterkt und die lieb gegen alle menschen in uns erwachse und zuneme.',
          tr_sub=[('everlasting God and Father, a Lord', 'everlasting God and Father of our Lord Jesus Christ, a Lord')]),
        P('civil-authority', tr_from=('wuerttemberg_1553_short', 3),
          p='Wöllest auch der weltlichen oberkeit, den römischen keiser, allen königen, fürsten und herrn, insonderheit aber einen erbarn, weisen rat diser stat Rotenburg, unsern herrn, auch allen iren amptleuten gnad und einigkeit verleihen, die untertanen nach deinem götlichen willen und wolgefallen zu regiren, auf das die gerechtigkeit gefürdert, die bosheit verhindert und gestraft werde, darmit wir in stiler ruhe und gutem friden, als christen gebürt, unser leben volstrecken mögen,',
          tr_sub=[('but especially unto our gracious lord and prince of this land, and also the whole house of Württemberg, together with all their counsellors and officers,',
                   'but especially unto an honourable and wise council of this city of Rothenburg, our lords, and also all their officers,')]),
        P('enemies', tr_from=('wuerttemberg_1553_short', 4),
          p='das auch unsere feind und widersacher ablassen, und sich mit uns friedlich und sanftmütiglich zu leben begeben wollen.',
          tr_sub=[('peaceably and gently', 'peaceably and meekly')]),
        P('afflicted', sub='childbirth; persecuted', tr_from=('wuerttemberg_1553_short', 5),
          p='Alle die so in trübsal, armut, krankheit, kindsbanden und andern anfechtung seien, auch die, so umb deines heiligen namens und der warheit willen angefochten, gefangen oder sonst verfolgung leiden, tröst sie, o Gott, mit deinem Heiligen Geist, das sie solches alles für deinen väterlichen willen aufnemen und erkennen!'),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_short', 6),
          p='Wöllest uns auch alle frucht der erden, zu leiblicher notturft gehörig, mit fruchtbarer wachsung geraten und gedeihen lassen.'),
        P('conclusion', tr_from=('wuerttemberg_1553_short', 7),
          p='Auch bitten wir für alles, darfür du, ewiger Gott, gebeten sein wilt, das du uns solches gnediglich verleihest, durch das bitter leiden und sterben Christi Jesu deines einigen Sohns, unsers geliebten Herrn und Heilands, welcher mit dir und dem Heiligen Geist, lebt und regiert, gleicher Gott hochgelobt in ewigkeit. Amen.'),
        P('lords-prayer',
          r='Und sprech ein jedes ein Vater unser darauf!', r_en='And let every one say an Our Father thereupon.'),
    ]))

W.append(dict(
    key='noerdlingen_1579', doc=375, year=1579,
    order='Nördlingen, Kirchenordnung',
    territory='Nördlingen (Imperial city)',
    citation='Sehling 12, VIII.7, pp. 367–368',
    family='B2. Württemberg short form', form='exhortation + continuous prayer',
    tradition='Lutheran',
    position='On Sundays and feast days immediately after the sermon.',
    heading='Vorrede des gemeinen gebets',
    heading_en='Preface of the common prayer',
    notes='The Württemberg long-form preface is printed, but instead of its collects (“miteinander also beten etc.”) the order gives, as “Oder”, the Württemberg short form; then announcements of the sick, marriages and feast days, the Our Father and the apostolic greeting (2 Cor 13:14).',
    petitions=[
        P('exhortation', tr_from=('wuerttemberg_1553_long', 1),
          r='Vorrede des gemeinen gebets.',
          b='Nachdem wir bei einander in Gottes namen versamlet seind und uns bevolhen ist, das wir Gott in aller unser not sollen anruefen, auch für meniglich unser fürbitte tun, zu welchem wir die zusagung unsers lieben Herrn Jesu Christi haben: Wo zween under euch eins werden auf erden, warumb es ist das sie piten wöllen, das sol inen von meinem Vater im himel widerfahren, und: Bittet, so würd euch gegeben! Suechet, so werdet ir finden! Klopfet an, so würd euch aufgeton! Hierauf laßt uns aus wahrem vertrauen zue göttlicher barmherzigkait durch unsern Herrn Jesum Christum, miteinander also beten etc.',
          tr_sub=[('our dear Lord Christ:', 'our dear Lord Jesus Christ:'),
                  ('knock, and it shall be opened unto you.', 'knock, and it shall be opened unto you. Hereupon let us, out of true confidence in the divine mercy, through our Lord Jesus Christ, pray together thus, etc.')]),
        P('exhortation', tr_from=('wuerttemberg_1553_short', 1),
          r='Oder:', r_en='Or:',
          b='Ir geliebten in Christo! Dieweil wir alle glider eines leibs seind, welches haupt Christus ist, so soll sich je ein glid des andern annemen und für einander piten. Das sollen wir aus bevelch unsern Herrn Christi und seines heiligen apostels Sant Pauli von herzen geren tun. Betet derwegen mit mir also!',
          tr_sub=[('and of his holy Apostle. Pray ye thus:', 'and of his holy Apostle Saint Paul. Pray ye therefore with me thus:')]),
        P('church', sub='ministers', tr_from=('wuerttemberg_1553_short', 2),
          p='Allmechtiger, barmherziger, ewiger Gott und Vater unsers Herrn Jesu Christi, ein Herr himels und der erden! Wir bitten dich herziglich, du wöllest deine heilige kürchen mit iren dienern durch den Heiligen Geist regiern, auf das sie bei der rechtgeschaffnen waide deines allmechtigen und ewigen worts erhalten werden, dardurch der glaube gegen dir gesterkt und die liebe gegen allen menschen in uns erwachse und zuneme.',
          tr_sub=[('everlasting God and Father, a Lord', 'everlasting God and Father of our Lord Jesus Christ, a Lord')]),
        P('civil-authority', tr_from=('wuerttemberg_1553_short', 3),
          p='Wellest auch der weltlichen oberkait dem römischen kaiser, allen königen, fürsten und herrn, insonderhait aber einem erbarn und wolwaisen rat, unser ordenlichen oberkait in diser statt sampt allen iren räten und amptleuten gnade und einigkeit verleihen, die undertonen nach deinem göttlichen willen und wolgefallen zu regieren, auf das die gerechtigkeit gefürdert, die bosheit verhindert und gestraft werde, damit wir in stiller rue und guetem friden, als christen gebürt, unser leben vollstrecken mögen!',
          tr_sub=[('but especially unto our gracious lord and prince of this land, and also the whole house of Württemberg, together with all their counsellors and officers,',
                   'but especially unto an honourable and right wise council, our lawful magistracy in this city, together with all their counsellors and officers,')]),
        P('enemies', tr_from=('wuerttemberg_1553_short', 4),
          p='Daß auch unsere feund und widersacher ablassen und sich mit uns fridlich und sanftmüetiglich zu leben begeben wöllen.',
          tr_sub=[('peaceably and gently', 'peaceably and meekly')]),
        P('afflicted', sub='childbirth; persecuted', tr_from=('wuerttemberg_1553_short', 5),
          p='Alle die, so in trüebsal, armuet, krankhait, kindsbanden und andern anfechtung seien, auch die, so umb deines heiligen namens und der warheit wilen angefochten, gefangen oder sonst verfolgung leiden, tröst sie, o Gott, mit deinem Heiligen Geist, das sie solches alles für deinen väterlichen willen aufnemen und erkennen!'),
        P('fruits-of-earth', tr_from=('wuerttemberg_1553_short', 6),
          p='Wöllest uns auch alle fruchte der erden, zur leiblichen notturft gehörig, mit fruchtbarer wachsung geraten und gedeien lassen!',
          note='“Wöhest” (OCR) read “Wöllest”.'),
        P('conclusion', tr_from=('wuerttemberg_1553_short', 7),
          p='Auch bitten wir umb alles, darumb du ewiger Gott gebeten sein wilt, das du uns solches gnediglich verleihest durch das bitter leiden und sterben Christi Jesu deines einigen Sohns unsers geliebten Herrn und Heilands, welcher mit dir und dem Heiligen Geist lebet und regieret, gleicher Gott, hochgelobt in ewigkeit. Amen.'),
        P('special', sub='lords-prayer; blessing',
          r='Darauf die sondere zufellige not als kranke, verkündigung der eheleut, feirtage etc. zu vermelden und mit dem Vater unser zu beschließen sampt dem segen:',
          r_en='Thereupon the special needs that befall, as the sick, the publishing of the married folk, feast days, etc., are to be announced, and it is to be concluded with the Our Father, together with the blessing:',
          p='Die gnade unsers Herrn Jesu Christi und die liebe Gottes und die gemeinschaft des Heiligen Geistes sei mit euch allen! Amen.',
          p_en='The grace of our Lord Jesus Christ, and the love of God, and the communion of the Holy Ghost, be with you all. Amen.'),
    ]))

W.append(dict(
    key='hohenlohe_1578', doc=574, year=1578,
    order='Hohenlohe, Kirchenordnung',
    territory='County of Hohenlohe',
    citation='Sehling 15, Nr. 25, pp. 263–264',
    family='B2. Württemberg short form', form='exhortation + continuous prayer',
    tradition='Lutheran',
    position='After the sermon, after the open confession and absolution (said here only when there are no communicants), the publishing of banns and prayer for the sick; followed by a psalm (“Erhalt uns Herr”, “Verleih uns Frieden”).',
    heading='Nach der predigt geschehe das gemein gebet für die not der gantzen christenheit',
    heading_en='After the sermon let the common prayer be made for the need of the whole of Christendom',
    notes='Prayer from Württemberg 1559 (short form), expanded: the sacraments in petition 1; a fuller petition for the counts and the local council; heretics in the petition for enemies; daily bread. The draft D had instead the Hanau-Lichtenberg 1573 exhortation. OCR slips (h for l) corrected silently.',
    petitions=[
        P('exhortation', sub='confession; special',
          r='Nach der predigt geschehe das gemein gebet für die not der gantzen christenheit auf nachfolgende weise: Erstlich, wann nicht communicanten vorhanden sind (dann wo derselben vorhanden, soll solches vor dem altar geschehen, wie im 7. capitel vom abendmal zu sehen ist), soll der prediger oder pfarrer dem volk die gemeine und offne beicht sampt der absolution darauf vorsprechen, darnach, nach der offnen beicht, alsbalden die angehenden eheleute verkündigen und für die kranken personen oder andere sonderbare anligen, so deren vorhanden, bitten, und dann nach sölchem allen das gebet verrichten wie volget:',
          r_en='After the sermon let the common prayer be made for the need of the whole of Christendom on this wise: First, when there are no communicants (for where there are such, this shall be done before the altar, as is to be seen in the seventh chapter, of the Supper), the preacher or pastor shall say before the people the common and open confession together with the absolution thereupon; thereafter, after the open confession, straightway publish the persons about to be married, and pray for the sick or other special needs, if there be any; and then, after all this, perform the prayer as followeth:',
          b='Erhebet ewre hertzen zu Gott, tragt im dise und die not der gantzen christenheit für und sprecht mit mir auß warem glauben und hertzlichem vertrawen also:',
          b_en='Lift up your hearts unto God, lay before him these needs and the need of the whole of Christendom, and say with me out of true faith and hearty confidence thus:'),
        P('church', sub='ministers; congregation',
          r='Gemeine gebet', r_en='Common prayer',
          p='Allmechtiger, barmhertziger, ewiger Gott und vatter, ein herr himels und der erden. Wir bitten dich hertzlich, du wöllest dein heilige kirch mit ihren dienern sampt uns durch den Heiligen Geist regieren, auf das sie bey der rechtschaffnen weid deines allerheiligsten und ewigen worts, sampt rechtem gebrauch und verstand der hochwürdigen sacramenten, erhalten werde, dardurch der glaub gegen dir gesterkt und die lieb gegen allen menschen in uns wachse und zuneme.',
          p_en='Almighty, merciful, everlasting God and Father, a Lord of heaven and of earth: we beseech thee heartily that thou wouldest govern thy holy Church with her ministers, together with us, by the Holy Ghost, that she may be kept in the right and true pasture of thy most holy and everlasting word, together with the right use and understanding of the most worthy sacraments, whereby faith toward thee may be strengthened, and love toward all men may grow and increase in us.'),
        P('civil-authority',
          p='Wöllest auch der weltlichen obrigkeit, dem römischen keiser, allen christlichen königen, fürsten und herrn, insonderheit aber unsern gnedigen herren und frawen, auch jungen herrn und frewlein von Hohenloe, sampt allen iren räten, amptleuten und dienern (auch einem erbarn rat oder einem ersamen gericht dises orts), gnad und einigkeit verleihen, damit sie das weltlich schwert, ihnen von dir befolhen, nach deinem bevelch in deiner forcht füren mögen. Erleuchte und erhalte sie bey deinem göttlichen namen; gib ihnen, lieber Herr, weißheit und verstand und ein friedlich regiment, auf das sie alle ire untertonen nach deinem göttlichen willen und wolgefallen regieren, die gerechtigkeit fördern, die boßheit verhindern und straffen. Erlengere inen die tag ires lebens und erleuchte sie mit deinem Heiligen Geist, darmit sie in deinem angefangnen werk, zu fördern das heilige wort Gottes, mit einem gottseligen eifer fortfaren und biß an das end bestendig verharren, auf das wir unter ihrer herrschaft deinen göttlichen namen sampt inen heiligen und preisen und, als christen gebürt, unser leben anrichten und füren mögen.',
          p_en='Vouchsafe also unto the temporal magistrates, the Roman Emperor, all Christian kings, princes and lords, but especially unto our gracious lords and ladies, and also the young lords and damsels of Hohenlohe, together with all their counsellors, officers and servants (and also an honourable council or a worshipful court of this place), grace and unity, that they may bear the temporal sword, committed unto them of thee, according to thy commandment in thy fear. Enlighten them and keep them in thy divine name; give them, dear Lord, wisdom and understanding and a peaceable government, that they may rule all their subjects according to thy divine will and good pleasure, further righteousness, hinder and punish wickedness. Prolong unto them the days of their life, and enlighten them with thy Holy Spirit, that they may go forward with godly zeal in thy work begun, to further the holy word of God, and continue steadfast unto the end; that under their dominion we together with them may hallow and praise thy divine name and, as becometh Christians, order and lead our life.'),
        P('enemies', sub='errant',
          p='Das auch unsere feind und widersacher von ihrer verfolgung ablassen; alle ketzer und verfürte sich bekeren und sich mit uns fridlich und sanftiglich zu leben begeben wöllen.',
          p_en='That our enemies and adversaries also may desist from their persecution; that all heretics and them that are led astray may be converted, and yield themselves to live with us peaceably and gently.'),
        P('afflicted', sub='childbirth; persecuted',
          p='Alle die, so in trübsalen, armut, krankheit, kindsbanden und andern anfechtungen; die auch, so umb deines heiligen worts willen angefochten, gefangen sind oder sonsten verfolgung leiden: tröste sie, o Gott, mit deinem Heiligen Geist, das sie solches alles vor deinen väterlichen willen aufnemen und erkennen.',
          p_en='All them that are in tribulations, poverty, sickness, the bonds of childbirth and other temptations; them also that for thy holy word’s sake are assailed, are taken captive, or otherwise suffer persecution: comfort them, O God, with thy Holy Spirit, that they may receive and acknowledge all this as thy fatherly will.'),
        P('fruits-of-earth',
          p='Wöllest uns auch das teglich brot gnediglichen geben und alle frücht der erden, zu leiblicher notturft gehörig, mit fruchtbarer wachsung geraten und gedeyen lassen.',
          p_en='Give us also graciously our daily bread, and cause all the fruits of the earth that pertain to our bodily need to prosper and thrive with fruitful increase.'),
        P('conclusion', tr_from=('wuerttemberg_1553_short', 7),
          p='Auch bitten wir für alles, darfür du, ewiger Gott, gebeten sein wilt, das du uns solches alles gnediglichen verleihest, durch das bitter leiden und sterben Christi Jesu, deines einigen sons, unsers geliebten herrn und heilands, welcher mit dir und dem Heiligen Geist lebt und regiert, gleicher Gott, hochgelobt in ewigkeit. Amen.',
          tr_sub=[('vouchsafe us the same', 'vouchsafe us all the same')]),
        P('lords-prayer',
          b='Betet auch ferner, wie uns Christus selbst geleret hat: Vatter unser, der du bist etc.',
          b_en='Pray ye also further, as Christ himself hath taught us: Our Father, who art, etc.'),
    ]))
